  if(req.method==='GET'&&path==='/api/v1/applications/me'){const u=await requireAuth(req,res);if(!u)return;if(pool){const r=await query(`SELECT a.id,p.slug AS "programmeId",p.title AS "programmeTitle",a.status,a.submitted_at AS "submittedAt",a.created_at AS "createdAt",a.review_note AS "reviewNote" FROM applications a JOIN programmes p ON p.id=a.programme_id WHERE a.applicant_user_id=$1 ORDER BY a.created_at DESC`,[u.id]);return send(res,200,{data:r.rows});}return send(res,200,{data:[...memory.applications.values()].filter(a=>a.userId===u.id)});}
  if(req.method==='POST'&&path==='/api/v1/public/enquiries'){const b=await jsonBody(req);const organisation=String(b.organisation||'').trim(),name=String(b.name||'').trim(),email=String(b.email||'').trim().toLowerCase(),scope=String(b.scope||'').trim(),goals=String(b.goals||'').trim();if(!organisation||!/^\S+@\S+\.\S+$/.test(email))return send(res,422,{error:{code:'VALIDATION_ERROR',message:'Organisation and valid business email are required.'}});let id=randomUUID();if(pool){await query('INSERT INTO corporate_enquiries(id,organisation,contact_name,email,team_scope,goals) VALUES($1,$2,$3,$4,$5,$6)',[id,organisation,name||null,email,scope||null,goals||null]);}else memory.enquiries.push({id,organisation,name,email,scope,goals,status:'new',createdAt:new Date().toISOString()});return send(res,201,{success:true,reference:id,message:'Your enquiry has been received.'});}
